-- [CHANGE-135] p_pssm_13060/mmlgap05_mon_inq.cpp L79-L84
select substr(START_TIME,1,6) as MONTH,sum(OUT_STEEL_WT) AS CONS_PROD_WT FROM (select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8)when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, OUT_STEEL_WT from TMMSM21 where FACTORY_DIV = 'A2') where START_TIME like '测试值' || '%' group by substr(START_TIME, 1, 6);

-- [CHANGE-136] p_pssm_13060/mmlgap05_mon_inq.cpp L98-L104
select substr(START_TIME, 1, 6) as MONTH, sum(SLAB_WT) AS SLAB_PROD_WT FROM(select case START_TIME WHEN to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(START_TIME, 1, 8) when to_date(START_TIME, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(START_TIME, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(START_TIME, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS START_TIME, SLAB_WT from(select a.SLAB_WT, a.STATION_NO, a.START_TIME from TMMSM33 a, TMMSM31 b where a.HEAT_NO = b.HEAT_NO and a.FACTORY_DIV = 'A2')) where START_TIME like '测试值' || '%' group by substr(START_TIME, 1, 6);

