FT JOIN(select STATION_NO, sum(OUT_STEEL_WT) AS WT_WEEK FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS')< to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8)when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING( BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS')THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where WEEK_ISO(to_date('测试值', 'YYYY-MM-DD')) = WEEK_ISO(to_date(BLOW_START_TIME1, 'YYYY-MM-DD')) GROUP BY STATION_NO)T3 ON T1.STATION_NO = T3.STATION_NO LEFT JOIN (select STATION_NO, sum(OUT_STEEL_WT) AS WT_DAY FROM(select case BLOW_START_TIME1 WHEN to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') >= to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') - 1 AND to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') < to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN SUBSTRING(BLOW_START_TIME1, 1, 8) when to_date(BLOW_START_TIME1, 'YYYY-MM-DD HH24:MI:SS') > to_date(CONCAT(SUBSTRING(BLOW_START_TIME1, 1, 8), '210000'), 'YYYY-MM-DD HH24:MI:SS') THEN to_char(to_date(SUBSTRING(BLOW_START_TIME1, 1, 8), 'YYYY-MM-DD') + 1, 'YYYYMMDD')END AS BLOW_START_TIME1, OUT_STEEL_WT, case STATION_NO WHEN STATION_NO = 1 THEN '1#转炉钢水' when STATION_NO = 2 THEN '2#转炉钢水' when STATION_NO = 3 THEN '3#转炉钢水' end as STATION_NO from TMMSM21 where FACTORY_DIV = 'A1' and BLOW_START_TIME1 <> '') where BLOW_START_TIME1 = '测试值' GROUP BY STATION_NO) T4 ON T1.ST