A.SLAB_THICK || '*' || A.SLAB_WIDTH MAT_SPECS, C.CAST_SUM, DECODE(D1.MAT_RCV, NULL, 0 , D1.MAT_RCV) || '/' || D.MAT_TUBE MAT_TUBE, A.CC_SEQ,A.RESTRAND_FLG,A.PONO,A.PONO_STATUS,A.ST_NO,A.SG_SIGN,A.PLAN_TAP_WT,A.HOT_SEND_FLAG,A.HOT_CHARGE_FLAG,A.PLAN_DATE,A.FACTORY_DIV,A.BACKLOG_EA FROM TPSSM10 A LEFT JOIN TPSSM11 B ON A.PONO = B.PONO LEFT JOIN (SELECT CAST_NO, COUNT(PONO) CAST_SUM FROM TPSSM11 WHERE CAST_NO <> ' ' GROUP BY CAST_NO) C ON B.CAST_NO = C.CAST_NO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_TUBE FROM TPSSM03 GROUP BY PONO) D ON A.PONO = D.PONO LEFT JOIN (SELECT PONO, COUNT(PONO) MAT_RCV FROM TPSSM03 WHERE SLAB_PROD_FLAG = '1' GROUP BY PONO) D1 ON A.PONO = D1.PONO WHERE 1=1 AND A.PONO_STATUS IN (15,16) AND A.CC_SEQ = 999 ORDER BY A.CC_SEQ,A.PLAN_DATE,A.CC_MACH_NO,B.CAST_NO,A.CAST_LOT_NO,A.CAST_LOT_DIV_NO );

